import fs from "node:fs"; import vm from "node:vm"; import crypto from "node:crypto";
const input=JSON.parse(fs.readFileSync(0,"utf8"));
const ctx=vm.createContext({TextEncoder,structuredClone,crypto:crypto.webcrypto});
new vm.Script(input.sources["static/calendar.js"]).runInContext(ctx);
const mods={}; for(const name of ["static/week_plan.mjs","static/week_file.mjs"]) mods[name]=new vm.SourceTextModule(input.sources[name],{context:ctx,identifier:name});
await mods["static/week_plan.mjs"].link(()=>{throw Error("unexpected import")});
await mods["static/week_file.mjs"].link(name=>{if(name!=="./week_plan.mjs")throw Error(name);return mods["static/week_plan.mjs"]});
await mods["static/week_file.mjs"].evaluate();
const read=mods["static/week_file.mjs"].namespace.readWeekFile, rows=mods["static/week_plan.mjs"].namespace.weekRows;
const date=vm.runInContext("(s)=>new Date(s)",ctx), output={};
for(const [name,text] of Object.entries(input.cases)){
 try{const r=read(text), writer=ctx.TasteTableCalendar.createWeekExport(r.state,{id:r.calendarId,createdAt:date(r.receivedAt)});
 output[name]={ok:true,calendar:writer.download(r.state,rows(r.state)),preview:writer.preview(r.state,rows(r.state)),source:writer.source,calendarId:r.calendarId};}
 catch(e){output[name]={ok:false,error:String(e.message)};}
}
console.log(JSON.stringify(output));
